package com.bananalab.lite;
import java.util.*;
final class SceneTakes{
 static CreatorSession.Result apply(String input,SceneDraft base,CreatorSession c)throws Exception{String q=ChatLanguage.normalize(input);if(q.matches("nueva serie desde aqui|reinicia la serie|recupera serie anterior|usa escenas guardadas|usa mis tomas actuales")){if(c.pending!=null)return CreatorSession.say("Resolvé el borrador antes de cambiar de serie.");if(q.equals("usa escenas guardadas")||q.equals("usa mis tomas actuales")){c.takeMode=q.equals("usa mis tomas actuales");return CreatorSession.say(c.takeMode?"La exportación de serie usará las tomas actuales.":"La exportación de serie usará las escenas guardadas.");}if(base==null)return CreatorSession.say("Primero creá una escena.");String current=pack(c,base);if(q.equals("recupera serie anterior")){if(c.takeBackup.isEmpty())return CreatorSession.say("No hay una serie anterior para recuperar.");org.json.JSONArray old=new org.json.JSONArray(c.takeBackup);if(old.length()<1||old.length()>8)return CreatorSession.say("La copia de serie no es válida.");SceneDraft restored=SceneDraft.read(old.getString(old.length()-1));CreatorSession.Result result=c.update(restored,false,"Recuperé la serie anterior y su última toma. La serie que estabas usando quedó como copia recuperable.");if(result.commit!=null){c.shots.clear();for(int i=0;i<old.length()-1;i++)c.shots.add(old.getString(i));c.takeBackup=current;c.takeMode=true;}return result;}c.takeBackup=current;c.shots.clear();c.takeMode=true;return CreatorSession.say("Empecé una serie nueva desde esta escena. ‘Recupera serie anterior’ restaura la anterior.");}if(q.matches("mis tomas|cuantas tomas hay"))return CreatorSession.say("La serie actual tiene "+(base==null?0:c.shots.size()+1)+" tomas. ‘Prepara siguiente toma’ conserva personajes y objetos al final de esta.");if(!q.matches("prepara siguiente toma|siguiente toma|continua en otra escena|prepara otra toma"))return null;if(c.pending!=null)return CreatorSession.say("Publicá o descartá el borrador antes de preparar otra toma.");if(base==null)return CreatorSession.say("Primero creá una escena.");if(c.shots.size()>=7)return CreatorSession.say("Esta serie admite ocho tomas; guardá la serie antes de empezar otra.");SceneConsistency.require(base);SceneDraft next=base.copy();Map<String,Float> end=ScenePositions.at(base,1);for(SceneDraft.Actor a:next.cast){float x=end.get(a.name);if(x<12||x>88)return CreatorSession.say("Un personaje terminó fuera del encuadre. Definí su regreso antes de preparar otra toma.");a.x=x;}for(SceneDraft.Prop p:next.props)p.holder=ObjectTransfer.at(base,p.id,1,ObjectTransfer.beats(base)).owner();next.actions.clear();next.actors.clear();next.slots.clear();next.targets.clear();next.recipients.clear();next.dialogue.clear();next.beatSeconds=3;next.fixedDuration=false;SceneConsistency.require(next);CreatorSession.Result result=c.update(next,false,"Preparé la siguiente toma con las identidades, voces, posiciones y portadores finales. La toma anterior quedó en la serie.");if(result.commit!=null){c.shots.add(base.json().toString());c.takeMode=true;}return result;}
 static String pack(CreatorSession c,SceneDraft base)throws Exception{org.json.JSONArray rows=new org.json.JSONArray();for(String old:c.shots)rows.put(old);rows.put(base.json().toString());return rows.toString();}

}
